# Source 00484 v13a p6: TFTs are required before each cycle, unlike 00483 monthly.
def fix_nivo28(v):
    replacements={'Thyroid tests once a month and when indicated; cortisol when clinically indicated.':'Thyroid tests before each cycle and when clinically indicated; cortisol when clinically indicated.', 'Thyroid function once a month and when clinically indicated.':'Thyroid function before each cycle and when clinically indicated.', 'Baseline; monthly and when indicated':'Baseline; before each cycle and when clinically indicated'}
    if isinstance(v,dict):return {k:fix_nivo28(x) for k,x in v.items()}
    if isinstance(v,list):return [fix_nivo28(x) for x in v]
    if isinstance(v,str):
        for old,new in replacements.items():v=v.replace(old,new)
    return v
